(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*10;
  const w2x = Math.sin((x+w1x)*0.025+t*0.4)*8 + Math.cos((y+w1y)*0.02-t*0.35)*6;
