  }
  const n=src.length,act=aS/n,inh=iS/n;
  const feed=0.035+Math.sin(t*0.15)*0.008,kill=0.062+Math.cos(t*0.12)*0.005;
  const reaction=act-act*act*act-inh+feed+lapA/n;
  const inhibition=(act-inh)*kill+lapI/n*0.5;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
