  const moire=Math.sin(sx*0.08)*Math.sin(sy*0.08)+Math.sin(sx*0.7+t*0.5)*Math.sin(sy*0.6-t*0.4)*0.6;
  const rdBlend=Math.tanh((reaction-inhibition*0.8+bg*0.25+spiral+moire*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend=rdBlend*0.7+cell*0.2+micro,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,85,115],[25,135,130],[80,165,120],
